after.tests/visible_test.py:
from src.tree import root_value

def check(name, values, expected):
    try:
        actual = root_value(values)
    except Exception as error:
        print(f"not ok - {name}\n  expected: {expected!r}\n  actual: raised {type(error).__name__}: {error}")
        return False
    if actual == expected:
        print(f"ok - {name}")
        return True
    print(f"not ok - {name}\n  expected: {expected!r}\n  actual: {actual!r}")
    return False

if __name__ == "__main__":
    cases = [
        ("ordinary tree", [8, 3, 10], 8),
        ("empty list", [], None),
        ("missing root", [None, 4], None),
        ("zero-valued root", [0, 5, 6], 0),
    ]
    passed = True
    for case in cases:
        if not check(*case):
            passed = False
    if not passed:
        raise SystemExit(1)

