import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { isBalanced, TreeNode } from '../src/balanced';
const n=(val:number,left:TreeNode|null=null,right:TreeNode|null=null):TreeNode=>({val,left,right});
test('ordinary balanced tree',()=>assert.equal(isBalanced(n(3,n(9),n(20,n(15),n(7)))),true));
test('empty tree boundary',()=>assert.equal(isBalanced(null),true));
test('leaf boundary',()=>assert.equal(isBalanced(n(1)),true));
test('root height difference greater than one',()=>assert.equal(isBalanced(n(1,n(2,n(3))),null as any),false));

